function lMcp(){ap('/api/system/status').then(function(d){var mc=d.mcp;if(!mc){$('mcpSt').innerHTML='<div class="mcp-blk"><div class="mcp-row"><span class="lbl">Status</span><span class="val" style="color:var(--t3)">No MCP client configured</span></div></div>';return}var ok=!mc.degraded;var h='<div class="mcp-blk">';h+='<div class="mcp-row"><span class="lbl">Status</span><span class="val" style="color:var('+(ok?'--ok':'--er')+');">'+(ok?'Healthy':'Degraded')+'</span></div>';h+='<div class="mcp-row"><span class="lbl">Cached Tools</span><span class="val">'+(mc.cachedTools||0)+'</span></div>';h+='<div class="mcp-row"><span class="lbl">Revision</span><span class="val">'+(mc.toolsRevision||0)+'</span></div>';h+='</div>';$('mcpSt').innerHTML=h}).catch(function(){$('mcpSt').innerHTML='<div class="err-state"><div class="err-msg">Could not load MCP status</div><button class="btn" onclick="lMcp()">Retry</button></div>'});lMcpCustom();lMcpPresetStatus();if(aPre){rMcpPr();return}ap('/api/presets').then(function(d){aPre=d;rMcpPr()}).catch(function(){})}
function rMcpPr(){var mcps=(aPre&&aPre.mcp)||[];var avail=window._mcpPresetStatus||{};$('mcpPr').innerHTML=mcps.map(function(m){var isOn=localStorage.getItem('cc_mcp_'+m.name)==='on';var ps=avail[m.name];var unavail=ps&&ps.available===false;var errHtml=unavail?'<div style="font-size:9px;color:var(--er);margin-bottom:4px">'+esc(ps.error||'Unavailable')+'</div>':'';var btnDisabled=unavail&&!isOn?' disabled style="opacity:0.5"':'';return'<div class="card'+(isOn?' style="border-color:var(--ok)"':'')+'"><div style="display:flex;align-items:center;gap:6px;margin-bottom:3px"><div class="led '+(isOn?'ok':'')+'"></div><h4 style="font-size:12px;font-weight:600">'+esc(m.name)+'</h4></div><div style="font-size:10px;color:var(--t2);line-height:1.5;margin-bottom:6px">'+esc(m.description||'')+'</div>'+errHtml+'<div id="mcpV_'+esc(m.name)+'" style="min-height:14px;margin-bottom:4px"></div><div style="display:flex;gap:4px"><button class="btn'+(isOn?' btn-p':'')+'"'+btnDisabled+' onclick="tgMcp(&apos;'+esc(m.name)+'&apos;,this)">'+(isOn?'Connected':'Connect')+'</button>'+(isOn?'<button class="btn" onclick="testMcp(&apos;'+esc(m.name)+'&apos;,this)">Test</button><button class="btn" onclick="mcpCustomReconnect(&apos;'+esc(m.name)+'&apos;,this)">Reconnect</button>':'')+'</div></div>'}).join('')||'<div class="em"><div class="em-s">No MCP presets available</div></div>'}
function lMcpPresetStatus(){ap('/api/mcp/presets/status').then(function(arr){var map={};(arr||[]).forEach(function(p){map[p.name]=p});window._mcpPresetStatus=map;rMcpPr()}).catch(function(){})}
function mcpAddOpen(){$('mcpName').value='';$('mcpCmd').value='';$('mcpArgs').value='';$('mcpDesc').value='';$('mcpEnvRows').innerHTML='<div style="display:flex;gap:4px;margin-bottom:4px"><input class="form-input" style="flex:1" placeholder="KEY" data-envk><input class="form-input" style="flex:1" placeholder="VALUE" data-envv></div>';$('mcpAddModal').classList.add('on')}
function mcpAddClose(){$('mcpAddModal').classList.remove('on')}
function mcpAddEnvRow(){var d=document.createElement('div');d.style.cssText='display:flex;gap:4px;margin-bottom:4px';d.innerHTML='<input class="form-input" style="flex:1" placeholder="KEY" data-envk><input class="form-input" style="flex:1" placeholder="VALUE" data-envv>';$('mcpEnvRows').appendChild(d)}
function mcpAddSubmit(){var name=$('mcpName').value.trim();var cmd=$('mcpCmd').value.trim();if(!name||!cmd){alert('Name and Command are required');return}var args=$('mcpArgs').value.trim();var desc=$('mcpDesc').value.trim();var env={};var rows=$('mcpEnvRows').querySelectorAll('div');rows.forEach(function(r){var k=r.querySelector('[data-envk]');var v=r.querySelector('[data-envv]');if(k&&v&&k.value.trim())env[k.value.trim()]=v.value});var hasEnv=Object.keys(env).length>0;ap('/api/mcp/servers',{method:'POST',body:JSON.stringify({name:name,command:cmd,args:args,description:desc||undefined,env:hasEnv?env:undefined})}).then(function(d){if(d.ok){mcpAddClose();lMcpCustom()}else{alert(d.error||'Failed to add server')}}).catch(function(e){alert('Error: '+e.message)})}
function lMcpCustom(){ap('/api/mcp/servers').then(function(d){var servers=d.servers||[];if(!servers.length){$('mcpCustom').innerHTML='<div class="em"><div class="em-s">No custom servers</div></div>';return}$('mcpCustom').innerHTML='<div class="grid">'+servers.map(function(s){var connState=localStorage.getItem('cc_mcp_custom_'+s.name);var isOn=connState==='on';return'<div class="card'+(isOn?' style="border-color:var(--ok)"':'')+'"><div style="display:flex;align-items:center;gap:6px;margin-bottom:3px"><div class="led '+(isOn?'ok':'')+'"></div><h4 style="font-size:12px;font-weight:600">'+esc(s.name)+'</h4><span class="tag" style="margin-left:auto">Custom</span></div><div style="font-size:10px;color:var(--t2);line-height:1.5;margin-bottom:4px">'+esc(s.description||s.command+' '+s.args.join(' '))+'</div><div id="mcpCV_'+esc(s.name)+'" style="min-height:14px;margin-bottom:4px"></div><div style="display:flex;gap:4px;flex-wrap:wrap"><button class="btn" onclick="mcpCustomTools(&apos;'+esc(s.name)+'&apos;,this)">Tools</button><button class="btn" onclick="mcpCustomReconnect(&apos;'+esc(s.name)+'&apos;,this)">Reconnect</button><button class="btn btn-danger" onclick="mcpCustomDel(&apos;'+esc(s.name)+'&apos;)">Delete</button></div></div>'}).join('')+'</div>'}).catch(function(){$('mcpCustom').innerHTML='<div class="err-state"><div class="err-msg">Could not load custom servers</div><button class="btn" onclick="lMcpCustom()">Retry</button></div>'})}
function mcpCustomDel(name){if(!confirm('Delete server '+name+'?'))return;ap('/api/mcp/servers/'+encodeURIComponent(name),{method:'DELETE'}).then(function(){localStorage.removeItem('cc_mcp_custom_'+name);lMcpCustom()}).catch(function(){})}
function mcpCustomTools(name,btn){btn.textContent='Loading...';btn.disabled=true;ap('/api/mcp/servers/'+encodeURIComponent(name)+'/tools').then(function(d){var tools=d.tools||[];var vEl=document.getElementById('mcpCV_'+name);if(vEl){if(tools.length){var h='<div style="margin-top:6px;border-top:1px solid var(--bd);padding-top:6px">';tools.forEach(function(t){h+='<div style="font-size:10px;margin-bottom:4px"><span style="color:var(--t0);font-weight:500">'+esc(t.name||t.registeredName||'')+'</span>';if(t.description)h+=' <span style="color:var(--t3)">'+esc(t.description.slice(0,80))+'</span>';h+='</div>'});h+='</div>';vEl.innerHTML=h}else{vEl.innerHTML='<span style="color:var(--t3);font-size:10px">No tools'+(d.error?' ('+esc(d.error)+')':'')+'</span>'}}btn.textContent='Tools';btn.disabled=false}).catch(function(){btn.textContent='Tools';btn.disabled=false})}
function mcpCustomReconnect(name,btn){btn.textContent='Reconnecting...';btn.disabled=true;ap('/api/mcp/servers/'+encodeURIComponent(name)+'/reconnect',{method:'POST'}).then(function(d){var vEl=document.getElementById('mcpCV_'+name);if(vEl){if(d.ok){vEl.innerHTML='<span style="color:var(--ok);font-size:10px">Reconnected</span>';localStorage.setItem('cc_mcp_custom_'+name,'on')}else{vEl.innerHTML='<span style="color:var(--er);font-size:10px">'+esc(d.error||'Failed')+'</span>'}}btn.textContent='Reconnect';btn.disabled=false;lMcpCustom()}).catch(function(){btn.textContent='Reconnect';btn.disabled=false})}
function skModalOpen(editSlug){$('skEditSlug').value=editSlug||'';$('skModalTitle').textContent=editSlug?'Edit Skill':'Create Skill';$('skModalSave').textContent=editSlug?'Save Changes':'Create Skill';if(editSlug&&aSk){var s=aSk.find(function(sk){return sk.slug===editSlug});if(s){$('skTitle').value=s.title||'';$('skSummary').value=s.summary||'';$('skTriggers').value=(s.triggerPhrases||[]).join('\\n');$('skSteps').value=(s.steps||[]).join('\\n');$('skTools').value=(s.requiredTools||[]).join(', ');}}else{$('skTitle').value='';$('skSummary').value='';$('skTriggers').value='';$('skSteps').value='';$('skTools').value=''}$('skModal').classList.add('on')}
function skModalClose(){$('skModal').classList.remove('on')}
function skModalSubmit(){var title=$('skTitle').value.trim();if(!title){alert('Title is required');return}var editSlug=$('skEditSlug').value;var payload={title:title,summary:$('skSummary').value.trim(),triggerPhrases:$('skTriggers').value.split('\\n').map(function(s){return s.trim()}).filter(Boolean),steps:$('skSteps').value.split('\\n').map(function(s){return s.trim()}).filter(Boolean),requiredTools:$('skTools').value?$('skTools').value.split(',').map(function(s){return s.trim()}).filter(Boolean):undefined};var method=editSlug?'PUT':'POST';var url=editSlug?'/api/skills/'+encodeURIComponent(editSlug):'/api/skills';ap(url,{method:method,body:JSON.stringify(payload)}).then(function(d){if(d.ok){skModalClose();aSk=null;rSk()}else{alert(d.error||'Failed')}}).catch(function(e){alert('Error: '+e.message)})}
