function skDel(slug){if(!confirm('Delete skill '+slug+'?'))return;ap('/api/skills/'+encodeURIComponent(slug),{method:'DELETE'}).then(function(d){if(d.ok){aSk=null;rSk()}else{alert(d.error||'Cannot delete')}}).catch(function(){})}
