var provCfgCache=null;
var provSlotNames=['primary','fallback','vision','compression','embedding'];
var provSlotLabels={primary:'Primary',fallback:'Fallback',vision:'Vision',compression:'Compression',embedding:'Embedding'};
function lProv(){ap('/api/providers/config').then(function(d){provCfgCache=d.config;rProv()}).catch(function(){$('provSlots').innerHTML='<div class="err-state"><div class="err-msg">Could not load provider config</div><button class="btn" onclick="lProv()">Retry</button></div>'})}
function rProv(){var h='';provSlotNames.forEach(function(sn){var slot=provCfgCache&&provCfgCache[sn]?provCfgCache[sn]:null;var isOptional=sn!=='primary';var ledColor=slot?'var(--ok,#22c55e)':'var(--t3,#666)';h+='<div class="card" style="margin-bottom:12px" data-provider-slot="'+sn+'">';h+='<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">';h+='<span style="width:8px;height:8px;border-radius:50%;background:'+ledColor+';display:inline-block"></span>';h+='<h4 style="font-size:13px;font-weight:600">'+esc(provSlotLabels[sn])+'</h4>';if(slot)h+='<span class="tag" style="font-size:10px">'+esc(slot.provider+'/'+slot.model)+'</span>';h+='</div>';if(slot){h+='<div style="font-size:11px;color:var(--t2);margin-bottom:8px">'+esc(slot.name||sn)+'</div>';h+='<div style="display:flex;gap:4px"><button class="btn" onclick="provTest(&quot;'+sn+'&quot;)">Test</button><button class="btn btn-danger" onclick="provRemoveSlot(&quot;'+sn+'&quot;)">Remove</button></div>'}else{h+='<div style="display:flex;gap:4px">';if(isOptional)h+='<button class="btn btn-p" onclick="provAddSlot(&quot;'+sn+'&quot;)">+ Add '+esc(provSlotLabels[sn])+' Model</button>';else h+='<button class="btn btn-p" onclick="provAddSlot(&quot;'+sn+'&quot;)">Configure Primary</button>';h+='</div>'}h+='</div>'});$('provSlots').innerHTML=h}
function provAddSlot(sn){var prov=prompt('Provider type (openai, anthropic, openrouter, custom):','openai');if(!prov)return;var model=prompt('Model name (e.g. gpt-4o, claude-sonnet-4):','gpt-4o');if(!model)return;var key=prompt('API key (leave empty to use primary):','');var cfg=provCfgCache||{};cfg[sn]={name:provSlotLabels[sn],provider:prov,model:model,apiKey:key||undefined};if(!cfg.primary&&sn!=='primary'){alert('Configure primary slot first');return}ap('/api/providers/config',{method:'POST',body:JSON.stringify(cfg)}).then(function(d){if(d.ok){provCfgCache=d.config;rProv()}else{alert(d.error||'Failed')}}).catch(function(e){alert('Error: '+e.message)})}
function provRemoveSlot(sn){if(sn==='primary'){if(!confirm('Remove primary provider config? This will clear all slots.'))return;ap('/api/providers/config',{method:'POST',body:JSON.stringify({primary:{name:'Primary',provider:'none',model:'none'}})}).then(function(){provCfgCache=null;rProv()}).catch(function(){})}else{var cfg=provCfgCache||{};delete cfg[sn];ap('/api/providers/config',{method:'POST',body:JSON.stringify(cfg)}).then(function(d){if(d.ok){provCfgCache=d.config;rProv()}}).catch(function(){})}}
function provTest(sn){var slot=provCfgCache&&provCfgCache[sn];if(!slot){alert('No config for slot '+sn);return}ap('/api/providers/test',{method:'POST',body:JSON.stringify({slot:sn,provider:slot.provider,model:slot.model,apiKey:slot.apiKey||'',baseUrl:slot.baseUrl||''})}).then(function(d){if(d.ok)alert('Test passed: '+d.response);else alert('Test failed: '+d.error)}).catch(function(e){alert('Error: '+e.message)})}
function lCfg(){ap('/api/system/status').then(function(d){var mc=d.mcp;var mcL=mc?(mc.degraded?'degraded':'healthy'):'not configured';var ps=[['Service',d.service||'--'],['Version',d.version||'--'],['Deployment',d.deployment||'--'],['Model',d.model||'--'],['Provider',d.provider||'--'],['Tools',''+(d.tools||[]).length],['MCP Status',mcL],['Plugins',(d.plugins||[]).join(', ')||'none']];$('cfB').innerHTML='<div class="cfg-blk">'+ps.map(function(p){return'<div class="kv"><span class="kv-k">'+esc(p[0])+'</span><span class="kv-v">'+esc(p[1])+'</span></div>'}).join('')+'</div>'}).catch(function(){$('cfB').innerHTML='<div class="err-state"><div class="err-msg">Could not load configuration</div><button class="btn" onclick="lCfg()">Retry</button></div>'})}
function lCfgState(){ap('/api/config/snapshot').then(function(d){if(d.activePreset)actPre=d.activePreset;if(d.activeToolset)actTs=d.activeToolset;if(d.disabledSkills){d.disabledSkills.forEach(function(s){localStorage.setItem('cc_sk_'+s,'off')})}if(d.gateways){Object.keys(d.gateways).forEach(function(gid){gwConfigured[gid]=!!d.gateways[gid]})}}).catch(function(){})}
function loadMemories(){var scope=$('memScope')?$('memScope').value:'';var url=sid?'/api/sessions/'+sid+'/memories':'';if(!url){$('memList').innerHTML='<div class="em"><div class="em-t">No memories yet</div><div class="em-s">Memories will appear here as the agent captures them</div></div>';return}if(scope)url+='?scope='+scope;$('memList').innerHTML='<div class="skeleton" style="width:80%"></div><div class="skeleton" style="width:60%"></div><div class="skeleton" style="width:70%"></div>';ap(url).then(function(d){allMem=d.records||[];filterMemories()}).catch(function(){$('memList').innerHTML='<div class="err-state"><div class="err-msg">Could not load memories</div><button class="btn" onclick="loadMemories()">Retry</button></div>'})}
function filterMemories(){var q=($('memSrch')?$('memSrch').value:'').toLowerCase();var f=allMem;if(q){f=allMem.filter(function(m){return(m.content||m.summary||'').toLowerCase().indexOf(q)!==-1||(m.tags||[]).join(' ').toLowerCase().indexOf(q)!==-1})}if(!f.length){$('memList').innerHTML='<div class="em"><div class="em-t">'+(allMem.length?'No matching memories':'No memories found')+'</div><div class="em-s">'+(allMem.length?'Try a different search term':'Memories will appear as the agent captures them')+'</div></div>';return}var h='<table class="mem-table"><thead><tr><th>Content</th><th>Tags</th><th>Scope</th><th>Created</th><th></th></tr></thead><tbody>';f.forEach(function(m,i){var content=m.content||m.summary||'';h+='<tr onclick="memDetail('+i+')">';h+='<td class="mem-content">'+esc(content.slice(0,80))+(content.length>80?'...':'')+'</td>';h+='<td>'+(m.tags||[]).map(function(t){return'<span class="tag">'+esc(t)+'</span>'}).join(' ')+'</td>';h+='<td><span class="tag">'+esc(m.scope||'session')+'</span></td>';h+='<td style="font-family:var(--m);font-size:10px;color:var(--t3)">'+ago(m.createdAt)+'</td>';h+='<td><button class="mem-del" onclick="event.stopPropagation();memDel(&apos;'+esc(m.id||'')+'&apos;)">&#10005;</button></td>';h+='</tr>'});h+='</tbody></table>';$('memList').innerHTML=h}
function memDetail(idx){var q=($('memSrch')?$('memSrch').value:'').toLowerCase();var filtered=allMem;if(q){filtered=allMem.filter(function(m){return(m.content||m.summary||'').toLowerCase().indexOf(q)!==-1||(m.tags||[]).join(' ').toLowerCase().indexOf(q)!==-1})}var m=filtered[idx];if(!m)return;var h='<div style="margin-bottom:12px"><div class="form-label">Content</div><div style="font-size:12px;color:var(--t1);line-height:1.6;white-space:pre-wrap;background:var(--b2);border:1px solid var(--bd);padding:10px">'+esc(m.content||m.summary||'')+'</div></div>';h+='<div style="margin-bottom:12px"><div class="form-label">Tags</div><div style="display:flex;flex-wrap:wrap;gap:4px">'+(m.tags||[]).map(function(t){return'<span class="tag">'+esc(t)+'</span>'}).join('')+'</div></div>';h+='<div style="margin-bottom:12px"><div class="form-label">Scope</div><span class="tag">'+esc(m.scope||'session')+'</span></div>';if(m.createdAt)h+='<div><div class="form-label">Created</div><span style="font-size:11px;color:var(--t2);font-family:var(--m)">'+esc(m.createdAt)+'</span></div>';$('memModalBody').innerHTML=h;$('memModal').classList.add('on');trapFocus($('memModal').querySelector('.modal-box'))}
function memModalClose(){$('memModal').classList.remove('on')}
function memDel(id){if(!confirm('Delete this memory?'))return;ap('/api/memories/'+id,{method:'DELETE'}).then(function(){loadMemories()}).catch(function(){})}
function jbModalOpen(){$('jbModal').classList.add('on');$('jbName').value='';$('jbTask').value='';$('jbSchedVal').value='60';$('jbModel').value='';$('jbDelPlatform').value='';$('jbDelChannel').value='';jbSchedChange();var skH='';(aSk||[]).forEach(function(s){skH+='<label class="form-checkbox"><input type="checkbox" value="'+esc(s.slug)+'">'+esc(s.title)+'</label>'});$('jbSkills').innerHTML=skH||'<span style="font-size:10px;color:var(--t3)">No skills available</span>';trapFocus($('jbModal').querySelector('.modal-box'))}
function jbModalClose(){$('jbModal').classList.remove('on')}
